FROM (
SELECT "billing_period" AS "d8ff07f9-bc56-4b6d-9388-f9e2cdd74d78.billing_period", "month" AS "d8ff07f9-bc56-4b6d-9388-f9e2cdd74d78.month", "year" AS "d8ff07f9-bc56-4b6d-9388-f9e2cdd74d78.year", "payer_account_id" AS "d8ff07f9-bc56-4b6d-9388-f9e2cdd74d78.payer_account_id", "unblended_cost" AS "d8ff07f9-bc56-4b6d-9388-f9e2cdd74d78.unblended_cost", "linked_account_id" AS "d8ff07f9-bc56-4b6d-9388-f9e2cdd74d78.linked_account_id", "usage_date" AS "d8ff07f9-bc56-4b6d-9388-f9e2cdd74d78.usage_date"
FROM "cid_cur"."compute_savings_plan_eligible_spend"
) AS "t"
LEFT JOIN (
SELECT "account_id" AS "7d72d7c7-85ae-4349-8b61-610af5393caf.account_id", "account_name" AS "7d72d7c7-85ae-4349-8b61-610af5393caf.account_name"
FROM "cid_cur"."account_map"
) AS "t0" ON "t"."d8ff07f9-bc56-4b6d-9388-f9e2cdd74d78.linked_account_id" = "t0"."7d72d7c7-85ae-4349-8b61-610af5393caf.account_id"

